"""The R17 chain's parameters for session.liq (on air since 2026-10-27, Lance): the ``param_*``
functions the chain scripts read, holding the values of the preset the clipping guard passed.
``scripts/write_session_params.py`` writes them to ``backend/playout/chain_params.liq``, and a
test fails when that file and the preset differ.
"""

from __future__ import annotations

import string

from processor_harness.presets import Preset
from processor_harness.render import liq_params

_SCRIPT = """\
# Generated by scripts/write_session_params.py from
# $source:
# the values of the preset the clipping guard passed (R17). Edit the preset, then regenerate;
# do not edit this file.
harness_floats = [$floats]
harness_ints = [$ints]
harness_bools = [$bools]
harness_strings = [$strings]
def param_float(name, default) = list.assoc(default=default, name, harness_floats) end
def param_int(name, default) = list.assoc(default=default, name, harness_ints) end
def param_bool(name, default) = list.assoc(default=default, name, harness_bools) end
def param_string(name, default) = list.assoc(default=default, name, harness_strings) end
"""


def script(preset: Preset) -> str:
    """The params script for ``preset``, naming the preset file it came from."""
    parts = preset.source.resolve().parts
    source = "/".join(parts[parts.index("scripts") :]) if "scripts" in parts else preset.source.name
    return string.Template(_SCRIPT).substitute(source=source, **liq_params(preset.params))
